{"cards": [{"node_code": "N_30c642ea839647f5", "definition": "研究城市建成区内部居民日常出行、公共交通运营及慢行系统组织的领域，涵盖市内路网交通流、公交线网规划及城市内部客运服务。", "boundary": "本节点严格限定于城市行政边界或建成区内部的交通活动。若涉及穿越城市但不以城市为起终点的过境交通，归入过境交通运输；若涉及城市与周边乡镇或邻市的连接，归入城乡运输或市际运输。本节点侧重“内部”属性，不包含城市对外枢纽的宏观布局。", "includes": ["城市内部公交、地铁、有轨电车等公共交通运营", "城市内部道路网交通组织、慢行系统及停车管理", "城市内部居民日常通勤、生活出行行为分析"], "excludes": ["穿越城市但不以城市为起终点的过境交通（归入过境交通运输）", "城市与周边乡镇或邻市之间的连接运输（归入城乡运输或市际运输）"], "sibling_distinctions": [{"other_code": "N_7f58dc8be5c133c6", "rule": "本节点侧重以城市为起终点或目的地的内部交通；兄弟节点侧重穿越城市、不以城市为起终点的过境交通。"}, {"other_code": "N_7c071be4bba6bf4b", "rule": "本节点侧重城市建成区内部；兄弟节点侧重城市与乡村地域之间的连接与互动。"}], "cross_boundary_rule": "涉及城市内部交通的经济分析归入城市交通运输经济；涉及城市内部交通的纯算法优化归入系统工程。"}, {"node_code": "N_7f58dc8be5c133c6", "definition": "研究穿越城市区域但不以该城市为起终点或目的地的交通组织、通道规划及过境交通对城市内部影响缓解的领域。", "boundary": "本节点聚焦于“穿越”属性，即交通流主要功能是连接城市外部两点，城市仅为通道。若交通流以城市为起终点，归入市内交通运输；若涉及城市对外枢纽的集散功能，需结合具体业务判断是否归入市际或入境/离境。本节点关注过境交通与城市内部交通的分离与协调。", "includes": ["城市过境公路、快速路及铁路通道的规划与组织", "过境交通对城市内部拥堵、安全的影响分析及缓解措施", "城市外围过境交通网络与内部路网的衔接设计"], "excludes": ["以城市为起终点或目的地的市内交通（归入市内交通运输）", "城市对外枢纽的宏观布局与多式联运组织（归入综合运输体制与结构或市际运输）"], "sibling_distinctions": [{"other_code": "N_30c642ea839647f5", "rule": "本节点侧重穿越城市的过境交通；兄弟节点侧重以城市为起终点的内部交通。"}, {"other_code": "N_45c642ea839647f5", "rule": "本节点侧重穿越城市的过境交通；兄弟节点侧重进入城市行政边界或枢纽的入境交通。"}], "cross_boundary_rule": "涉及过境交通的经济评价归入城市交通运输经济；涉及过境交通流的仿真算法归入系统工程。"}, {"node_code": "N_45c642ea839647f5", "definition": "研究从城市外部进入城市行政边界、交通枢纽或主要集散区域的交通组织、引导及入境交通服务管理的领域。", "boundary": "本节点聚焦于“进入”动作，即交通流从外部空间进入城市空间的过程。若交通流仅穿越城市而不进入内部或枢纽，归入过境交通运输；若涉及离开城市的交通，归入离境交通运输。本节点关注入境交通的顺畅性、安全性及与城市内部交通的衔接。", "includes": ["城市入口、收费站、枢纽站点的入境交通组织", "入境交通引导系统、标识标牌及信息服务", "入境交通与城市内部公交、出租车的衔接服务"], "excludes": ["仅穿越城市而不进入内部或枢纽的过境交通（归入过境交通运输）", "离开城市的交通组织（归入离境交通运输）"], "sibling_distinctions": [{"other_code": "N_7f58dc8be5c133c6", "rule": "本节点侧重进入城市边界或枢纽的入境交通；兄弟节点侧重穿越城市但不进入内部的过境交通。"}, {"other_code": "N_763c8cefee5accf4", "rule": "本节点侧重进入城市的交通；兄弟节点侧重离开城市的交通。"}], "cross_boundary_rule": "涉及入境交通的经济分析归入城市交通运输经济；涉及入境交通流的智能引导算法归入系统工程。"}]}
```

